@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;1,600;1,700&display=swap');
:root{--ink:#f4f3e8;--muted:#9c9e8e;--gold:#e4c87a;--green:#182219;--line:#ffffff24;--ui:Manrope,system-ui,sans-serif;--mono:'DM Mono',monospace}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#111710;color:var(--ink);font-family:var(--ui);overflow:hidden}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:100dvh;background:#182219;overflow:hidden;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,#080d0a99 100%),linear-gradient(180deg,#09110c88,transparent 23%,transparent 73%,#080c09a8);z-index:1}.topbar{position:absolute;z-index:3;left:0;right:0;top:0;padding:24px 4.2vw;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:800;letter-spacing:.24em}.brand-mark{color:var(--gold);font-size:23px}.brand small{font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:#d4d8c6;margin-left:4px;padding-left:13px;border-left:1px solid var(--line);font-weight:400}.top-right{display:flex;align-items:center;gap:10px;font:10px var(--mono);letter-spacing:.1em;color:#d9ddcc;pointer-events:auto}.live-dot{height:7px;width:7px;border-radius:50%;background:#df7059;box-shadow:0 0 12px #df7059}.icon-btn{width:36px;height:36px;border:1px solid #ffffff3b;background:#10191299;border-radius:50%;cursor:pointer;color:#e5dfc7;font-size:16px}.screen{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:100px 9.5% 65px;background:linear-gradient(90deg,#0b110de6 0%,#101811b8 37%,#10181136 73%,#1018114a)}.hidden{display:none!important}.menu-copy{align-self:center;margin-top:-3vh}.eyebrow,.section-label{font:10px var(--mono);letter-spacing:.19em;color:var(--gold)}.eyebrow:before{content:'';display:inline-block;width:25px;height:1px;background:var(--gold);vertical-align:middle;margin-right:10px}.menu-copy h1{font-size:clamp(54px,8.3vw,110px);line-height:.91;letter-spacing:-.075em;margin:19px 0 22px;font-weight:600}.menu-copy h1 em{font-family:'Playfair Display',serif;color:var(--gold);font-weight:600;letter-spacing:-.06em}.menu-copy p{font-size:13px;line-height:1.9;color:#b8bdad}.setup-panel{width:min(390px,39vw);background:#121b14d9;border:1px solid #ffffff24;padding:23px 24px 17px;box-shadow:0 25px 90px #0006;backdrop-filter:blur(16px)}.section-label{display:flex;justify-content:space-between;color:#e7e5d7;font-size:9px;margin:0 0 12px}.section-label span{color:#8e9788}.map-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.map-option{position:relative;cursor:pointer;height:71px;border:1px solid #ffffff2a;overflow:hidden;background:#27362b;padding:0;text-align:left;transition:.2s}.map-option:before{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#101510e8,transparent 80%),var(--map-image);opacity:.85;transition:.2s}.map-option:after{content:'';position:absolute;inset:0;border:1px solid transparent;pointer-events:none}.map-option:hover:before{opacity:1}.map-option.selected{border-color:var(--gold);box-shadow:inset 0 0 0 1px var(--gold)}.map-option.selected:after{border-color:#e4c87a55}.map-option b,.map-option small{position:absolute;z-index:1;left:8px;bottom:15px;font-size:9px;letter-spacing:.05em}.map-option small{bottom:4px;font:7px var(--mono);color:#c0c6b5}.map-option:nth-child(1){--map-image:radial-gradient(ellipse at 70% 20%,#acc28344,transparent 44%),linear-gradient(135deg,#405735,#1a3426 55%,#202c1c)}.map-option:nth-child(2){--map-image:radial-gradient(ellipse at 60% 20%,#dab57a55,transparent 46%),linear-gradient(135deg,#755a3a,#3a4232 60%,#51422e)}.map-option:nth-child(3){--map-image:radial-gradient(ellipse at 60% 20%,#e6803b66,transparent 44%),linear-gradient(135deg,#663b2b,#392923 58%,#7d4428)}.class-label{margin-top:22px}.class-list{display:g