font-size:12px;margin-right:4px}.storm-label b{color:#fff;margin-left:6px}.storm-track,.health-track{height:3px;background:#ffffff40;margin-top:8px;overflow:hidden}.storm-track i,.health-track i{height:100%;display:block;width:100%;background:#df795e;transition:width .2s}.hud-right{position:absolute;top:23px;right:4.2%;display:flex;align-items:center;gap:12px}.health-wrap{width:130px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:7px}.health-wrap>span{font:7px var(--mono);color:#dadfd0;letter-spacing:.08em;grid-column:1/4}.health-track{grid-column:1/3;margin-top:0;height:5px}.health-track i{background:#9abd78}.health-wrap>b{font:10px var(--mono)}.spell-card{position:absolute;left:4.2%;bottom:32px;display:flex;align-items:center;gap:10px;background:#101811c9;border:1px solid #ffffff35;padding:9px 13px;min-width:200px;backdrop-filter:blur(8px)}.spell-card>span{font-size:22px;color:var(--spell,#e69b61)}.spell-card div:nth-child(2){display:grid;gap:3px;flex:1}.spell-card small{font:7px var(--mono);color:#aab2a1;letter-spacing:.1em}.spell-card b{font-size:9px;letter-spacing:.07em}.spell-cooldown{font:7px var(--mono);color:#daca92;border-left:1px solid #ffffff2e;padding-left:9px}.crosshair{position:absolute;left:50%;top:50%;width:20px;height:20px;transform:translate(-50%,-50%);opacity:.87}.crosshair i{position:absolute;background:#fff3dc;width:1px;height:5px}.crosshair i:nth-child(1){top:0;left:9px}.crosshair i:nth-child(2){bottom:0;left:9px}.crosshair i:nth-child(3){left:0;top:8px;height:1px;width:5px}.crosshair i:nth-child(4){right:0;top:8px;height:1px;width:5px}.crosshair b{position:absolute;width:2px;height:2px;border-radius:50%;background:#f5dc9a;left:9px;top:9px}.feed{position:absolute;right:4.2%;top:94px;display:grid;gap:5px;text-align:right;font:8px var(--mono);color:#e4e6d9}.feed div{animation:fadefeed 4s forwards;background:#11181099;padding:6px 9px;border-right:2px solid var(--gold)}@keyframes fadefeed{0%,75%{opacity:1}100%{opacity:0}}.desktop-help{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font:7px var(--mono);letter-spacing:.08em;color:#e2e3d455;white-space:nowrap}.desktop-help span{color:#e4c87a;margin:0 7px}.touch-controls{display:none}.damageFlash{position:absolute;inset:0;box-shadow:inset 0 0 80px #ec4a3570;opacity:0}.touch-controls{pointer-events:none}.joystick,.action-btn{pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none}.toast{position:absolute;z-index:8;top:19%;left:50%;transform:translate(-50%,-10px);padding:10px 18px;background:#121b14e8;border:1px solid #e4c87a88;color:#eed991;font:9px var(--mono);letter-spacing:.1em;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}#overlay{justify-content:center;align-items:center;background:#090e0bc9;backdrop-filter:blur(7px)}.result-card{width:min(430px,90vw);border:1px solid #ffffff35;background:#131c15;padding:34px 38px;text-align:center;box-shadow:0 30px 100px #0008}.result-card .eyebrow:before{display:none}.result-card h2{font-size:48px;letter-spacing:-.06em;margin:9px 0;color:var(--gold)}.result-card p{font-size:12px;color:#bdc2b3}.result-stats{display:flex;justify-content:space-between;margin:27px 0 7px;border-top:1px solid #ffffff22;border-bottom:1px solid #ffffff22;padding:15px 0}.result-stats div{display:grid;gap:5px}.result-stats b{font-size:18px}.result-stats small{font:7px var(--mono);color:#a8ad9e}.text-btn{background:none;border:0;color:#aeb3a4;font:8px var(--mono);letter-spacing:.1em;margin-top:14px;cursor:pointer}
@media(max-width:800px){.topbar{padding:15px 17px}.brand{font-size:12px;gap:7px}.brand-mark{font-size:18px}.brand small{font-size:7px;padding-left:8px}.top-right{font-size:8px;gap:7px}.top-right .icon-btn{width:30px;height:30px}.screen{padding:78px 7vw 45px;background:linear-gradient(90deg,#0b110de8,#10181199 75%,#10181155);}.menu-copy{position:absolute;left:7vw;top:12%;margin:0}.menu-copy h1{font-size:clamp(47px,12vw,76px);margin:12px 0}.menu-copy p{font-size:11px}.setup-panel{position:absolute;bottom:5vh;left:50%;transform:translateX(-50%);width:min(410px,88vw);padding:15px 17px 12px}.section-label{font-size:8px;margin-bottom:8px}.map-option{height:58px}.map-option b{font-size:8px}.map-option small{font-size:6px}.class-label{margin-top:12px}.class-list{grid-template-columns:repeat(3,1fr);gap:5px}.class-option{height:65px;display:flex;flex-direction:column;justify-content:center;gap:2px;padding:4px}.class-glyph{width:auto;height:auto;background:none;font-size:16px}.class-meta{display:flex;align-items:center}.class-meta b{font-size:8px}.class-meta small{display:none}.class-tag{font-size:6px}.primary-btn{height:40px;margin-top:12px;font-size:9px}.menu-foot{margin-top:9px;font-size:6px}.menu-note{left:7vw;bottom:13px;font-size:6px}.hud-left{left:12px;top:64px;gap:5px}.stat-box{min-width:77px;height:39px;padding:5px 7px;gap:6px}.stat-icon{font-size:14px}.stat-box b{font-size:10px}.stat-box small{font-size:6px}.hud-center{top:16px;width:130px}.storm-label{font-size:7px}.storm-track{margin-top:5px}.hud-right{top:13px;right:12px;gap:7px}.health-wrap{width:92px;gap:4px}.health-wrap>span{font-size:6px}.health-wrap>b{font-size:8px}.hud-right .icon-btn{width:29px;height:29px}.spell-card{left:12px;bottom:22px;min-width:150px;padding:6px 9px;gap:7px}.spell-card>span{font-size:17px}.spell-card small{font-size:6px}.spell-card b{font-size:7px}.spell-cooldown{font-size:6px;padding-left:6px}.feed{top:113px;right:12px;font-size:7px}.desktop-help{display:none}.touch-controls{display:block;position:absolute;inset:0}.joystick{position:absolute;left:22px;bottom:38px;width:112px;height:112px;display:grid;place-items:center}.joy-ring{position:absolute;width:92px;height:92px;border:1px solid #ffffff45;border-radius:50%;background:#10181140;box-shadow:inset 0 0 22px #ffffff0b}.joy-knob{position:absolute;width:39px;height:39px;border-radius:50%;background:#e3c97c77;border:1px solid #f1d991bb;box-shadow:0 2px 12px #0008}.joystick small{position:absolute;bottom:-13px;font:6px var(--mono);letter-spacing:.12em;color:#ffffff9a}.touch-actions{position:absolute;right:20px;bottom:33px;display:flex;align-items:end;gap:13px}.action-btn{border:1px solid #ffffff70;border-radius:50%;display:grid;place-items:center;align-content:center;gap:1px;background:#152017b8;backdrop-filter:blur(6px)}.action-btn span{font-size:24px;line-height:24px;color:var(--gold)}.action-btn small{font:6px var(--mono);letter-spacing:.05em}.jump-btn{width:55px;height:55px}.cast-btn{width:71px;height:71px;border-color:#e4c87a;background:#3a3123bf}.cast-btn span{font-size:26px}.damageFlash{pointer-events:none}#aliveLabel{font-size:7px}.result-card{padding:28px 23px}.result-card h2{font-size:39px}}
@media(max-height:700px) and (max-width:800px){.menu-copy{top:10%}.menu-copy h1{font-size:48px}.menu-copy p{display:none}.setup-panel{bottom:3vh;padding:11px 15px 9px}.map-option{height:48px}.class-option{height:54px}.class-label{margin-top:9px}.primary-btn{margin-top:8px;height:36px}.menu-foot{display:none}.joystick{bottom:25px}.touch-actions{bottom:23px}}

(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d',{alpha:false});
const $=s=>document.querySelector(s),menu=$('#menu'),hud=$('#hud'),overlay=$('#overlay');
const maps=[
 {name:'Bosque Eterno',sub:'RUÍNAS VIVAS',theme:'forest',ground:'#34432d',ground2:'#283b2a',wall:'#536347',wall2:'#374838',sky1:'#344b45',sky2:'#e1ad75',accent:'#9dc47b'},
 {name:'Ruínas Douradas',sub:'DESERTO ANTIGO',theme:'desert',ground:'#806746',ground2:'#66543b',wall:'#9f8157',wall2:'#705a3d',sky1:'#555e63',sky2:'#e0a66b',accent:'#f2ce82'},
 {name:'Cratera Rubra',sub:'TERRAS DE BRASA',theme:'lava',ground:'#51372f',ground2:'#392b28',wall:'#765044',wall2:'#4c3430',sky1:'#372d37',sky2:'#e17e51',accent:'#ff9461'}
];
const classes=[
 {name:'Piro',spell:'BRASA ARCANA',glyph:'✹',tag:'DANO',color:'#f49a63',desc:'Explosão ardente · dano elevado',damage:37,cooldown:1.55,range:19},
 {name:'Névoa',spell:'LANÇA GLACIAL',glyph:'❄',tag:'CONTROLE',color:'#8ed8eb',desc:'Gelo preciso · congela o alvo',damage:26,cooldown:1.25,range:23},
 {name:'Íris',spell:'RAIO VIOLETA',glyph:'ϟ',tag:'RÁPIDO',color:'#c6a0fa',desc:'Relâmpago veloz · alcance longo',damage:22,cooldown:.85,range:25}
];
let selectedMap=0,selectedClass=0,world=[],W=26,H=26,player=null,enemies=[],effects=[],decor=[],state='menu',last=0,elapsed=0,storm=90,keys={},mouseDown=false,joy={x:0,y:0},joystickActive=false,turnTouch=null,castReady=0,level=1,kills=0,maxLevel=1,feedTimer=[],audioCtx=null,soundOn=false,frame=0;
let vw=innerWidth,vh=innerHeight,scale=1;
function resize(){vw=innerWidth;vh=innerHeight;scale=Math.min(devicePixelRatio||1,1.35);canvas.width=Math.floor(vw*scale);canvas.height=Math.floor(vh*scale);canvas.style.width=vw+'px';canvas.style.height=vh+'px';ctx.setTransform(scale,0,0,scale,0,0)}
addEventListener('resize',resize);resize();
function renderChoices(){
 $('#mapList').innerHTML=maps.map((m,i)=>`<button class="map-option ${i===selectedMap?'selected':''}" data-map="${i}"><b>${m.name}</b><small>${m.sub}</small></button>`).join('');
 $('#classList').innerHTML=classes.map((c,i)=>`<button class="class-option ${i===selectedClass?'selected':''}" data-class="${i}" style="--class-color:${c.color}"><span class="class-glyph">${c.glyph}</span><span class="class-meta"><b>${c.name}</b><small>${c.desc}</small></span><span class="class-tag">${c.tag}</span></button>`).join('');
 document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{selectedMap=+b.dataset.map;renderChoices()});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{selectedClass=+b.dataset.class;renderChoices()});
}
renderChoices();
function makeWorld(){W=26;H=26;world=Array.from({length:H},()=>Array(W).fill(0));for(let x=0;x<W;x++){world[0][x]=3;world[H-1][x]=3}for(let z=0;z<H;z++){world[z][0]=3;world[z][W-1]=3}
 let seed=9031+selectedMap*771;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 for(let z=3;z<H-3;z+=3)for(let x=3;x<W-3;x+=3){if(Math.abs(x-13)+Math.abs(z-13)<5)continue;if(rand()<.72){let ox=Math.floor(rand()*2),oz=Math.floor(rand()*2),type=selectedMap===0?(rand()<.72?2:1):selectedMap===1?(rand()<.72?1:3):(rand()<.68?3:1);world[z+oz][x+ox]=type}}
 for(let i=0;i<4;i++){let x=7+(i%2)*12,z=7+Math.floor(i/2)*12;world[z][x]=0;world[z][x+1]=0;world[z+1][x]=0}world[13][13]=0;
 decor=[];for(let i=0;i<80;i++){let x=1+rand()*(W-2),z=1+rand()*(H-2);if(world[z|0][x|0]===0&&Math.abs(x-13)+Math.abs(z-13)>2)decor.push({x,z,r:.035+rand()*.07,seed:rand()})}}
function free(x,z){return x>.7&&z>.7&&x<W-1.7&&z<H-1.7&&world[Math.floor(z)]?.[Math.floor(x)]===0&&world[Math.floor(z)]?.[Math.floor(x+.22)]===0&&world[Math.floor(z+.22)]?.[Math.floor(x)]===0}
function startGame(){makeWorld();let spawn=[[13,13],[13,13],[13,13]][selectedMap];player={x:spawn[0],z:spawn[1],a:-Math.PI/2,hp:100,maxHp:100,jump:0,jumpV:0,jumps:0,damage:0};enemies=[];for(let i=0;i<9;i++){let a=i*Math.PI*2/9,r=7.4+(i%3)*1.5,x=13+Math.cos(a)*r,z=13+Math.sin(a)*r;while(!free(x,z)){x=2+Math.random()*22;z=2+Math.random()*22}enemies.push({x,z,a:Math.atan2(13-z,13-x),hp:100,maxHp:100,alive:true,id:i+1,shoot:1+Math.random()*2,freeze:0,flash:0,move:Math.random()*5,color:['#db9c69','#9dbb85','#b694ce','#dbd0aa','#cb7d72'][i%5]})}
 state='playing';elapsed=0;storm=90;level=1;kills=0;maxLevel=1;castReady=0;effects=[];feedTimer=[];menu.classList.add('hidden');overlay.classList.add('hidden');hud.classList.remove('hidden');$('#spellName').textContent=classes[selectedClass].spell;$('#spellIcon').textContent=classes[selectedClass].glyph;$('#castGlyph').textContent=classes[selectedClass].glyph;$('#spellIcon').style.color=classes[selectedClass].color;$('#aliveLabel').textContent='10 MAGOS RESTANTES';$('#healthBar').style.width='100%';$('#healthText').textContent='100';$('#kills').textContent='0';$('#level').textContent='NÍVEL 1';$('#xpLabel').textContent='0 / 3 PARA EVOLUIR';if(soundOn)beep(440,.08);last=performance.now();requestAnimationFrame(loop);showToast('A ARENA ESTÁ ABERTA — BOA CAÇADA')}
$('#startBtn').onclick=startGame;$('#againBtn').onclick=startGame;$('#menuBtn').onclick=()=>{state='menu';hud.classList.add('hidden');overlay.classList.add('hidden');menu.classList.remove('hidden');renderChoices()};$('#pauseBtn').onclick=togglePause;
let paused=false;function togglePause(){if(state!=='playing')return;paused=!paused;showToast(paused?'PAUSADO — TOQUE Ⅱ PARA VOLTAR':'A ARENA ESTÁ ABERTA');if(!paused){last=performance.now();requestAnimationFrame(loop)}}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2100)}
function feed(t){let el=document.createElement('div');el.textContent=t;$('#feed').prepend(el);setTimeout(()=>el.remove(),4000)}
function beep(freq=350,duration=.08,type='sine'){if(!soundOn)return;try{audioCtx ||=new(window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫':'♪';if(soundOn)beep(580,.1)};
function endGame(win){if(state!=='playing')return;state='over';$('#resultEyebrow').textContent=win?'SOBREVIVENTE':'A ARENA RECLAMA MAIS UM';$('#resultTitle').textContent=win?'VITÓRIA':'ELIMINADO';$('#resultTitle').style.color=win?'#e4c87a':'#d97965';$('#resultDesc').textContent=win?'A arena agora pertence a você.':'A magia não termina aqui. Tente outra vez.';$('#resultKills').textContent=kills;$('#resultLevel').textContent=maxLevel;$('#resultTime').textContent=`${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;setTimeout(()=>overlay.classList.remove('hidden'),450);beep(win?660:160,.45,'triangle')}
function upgrade(){level=1+Math.floor(kills/3);if(level>maxLevel){maxLevel=level;showToast(`PODER EVOLUÍDO — NÍVEL ${level}`);feed('✦ MAGIA EVOLUÍDA · RECARGA MAIS RÁPIDA');player.hp=Math.min(player.maxHp,player.hp+12);beep(760,.2,'triangle')}$('#level').textContent=`NÍVEL ${level}`;$('#xpLabel').textContent=`${kills%3} / 3 PARA EVOLUIR`}
