content.text:
### Result
{
  "rule": [
    "@media (max-width: 800px) {
  #game-shell:has(#hud:not(.hidden)) > .topbar { display: none; }
  .topbar { padding: 15px 17px; }
  .brand { font-size: 12px; gap: 7px; }
  .brand-mark { font-size: 18px; }
  .brand small { font-size: 7px; padding-left: 8px; }
  .top-right { font-size: 8px; gap: 7px; }
  .top-right .icon-btn { width: 30px; height: 30px; }
  .screen { padding: 78px 7vw 45px; background: linear-gradient(90deg, rgba(11, 17, 13, 0.91), rgba(16, 24, 17, 0.6) 75%, rgba(16, 24, 17, 0.333)); }
  .menu-copy { position: absolute; left: 7vw; top: 12%; margin: 0px; }
  .menu-copy h1 { font-size: clamp(47px, 12vw, 76px); margin: 12px 0px; }
  .menu-copy p { font-size: 11px; }
  .setup-panel { position: absolute; bottom: 5vh; left: 50%; transform: translateX(-50%); width: min(410px, 88vw); padding: 15px 17px 12px; }
  .section-label { font-size: 8px; margin-bottom: 8px; }
  .map-option { height: 58px; }
  .map-option b { font-size: 8px; }
  .map-option small { font-size: 6px; }
  .class-label { margin-top: 12px; }
  .class-list { grid-template-columns: repeat(3, 1fr); gap: 5px; }
  .class-option { height: 65px; display: flex; flex-direction: column; justify-content: center; gap: 2px; padding: 4px; }
  .class-glyph { width: auto; height: auto; background: none; font-size: 16px; }
  .class-meta { display: flex; align-items: center; }
  .class-meta b { font-size: 8px; }
  .class-meta small { display: none; }
  .class-tag { font-size: 6px; }
  .primary-btn { height: 40px; margin-top: 12px; font-size: 9px; }
  .menu-foot { margin-top: 9px; font-size: 6px; }
  .menu-note { left: 7vw; bottom: 13px; font-size: 6px; }
  .hud-left { left: 12px; top: 64px; gap: 5px; }
  .stat-box { min-width: 77px; height: 39px; padding: 5px 7px; gap: 6px; }
  .stat-icon { font-size: 14px; }
  .stat-box b { font-size: 10px; }
  .stat-box small { font-size: 6px; }
  .hud-center { top: 16px; width: 130px; }
  .storm-label { font-size: 7px; }
  .storm-track { margin-top: 5px; }
  .hud-right { top: 13px; right: 12px; gap: 7px; }
  .health-wrap { width: 92px; gap: 4px; }
  .health-wrap > span { font-size: 6px; }
  .health-wrap > b { font-size: 8px; }
  .hud-right .icon-btn { width: 29px; height: 29px; }
  .spell-card { left: 12px; bottom: 22px; min-width: 150px; padding: 6px 9px; gap: 7px; }
  .spell-card > span { font-size: 17px; }
  .spell-card small { font-size: 6px; }
  .spell-card b { font-size: 7px; }
  .spell-cooldown { font-size: 6px; padding-left: 6px; }
  .feed { top: 113px; right: 12px; font-size: 7px; }
  .desktop-help { display: none; }
  .touch-controls { display: block; position: absolute; inset: 0px; }
  .joystick { position: absolute; left: 22px; bottom: 38px; width: 112px; height: 112px; display: grid; place-items: center; }
  .joy-ring { position: absolute; width: 92px; height: 92px; border: 1px solid rgba(255, 255, 255, 0.27); border-radius: 50%; background: rgba(16, 24, 17, 0.25); box-shadow: rgba(255, 255, 255, 0.043) 0px 0px 22px inset; }
  .joy-knob { position: absolute; width: 39px; height: 39px; border-radius: 50%; background: rgba(227, 201, 124, 0.467); border: 1px solid rgba(241, 217, 145, 0.733); box-shadow: rgba(0, 0, 0, 0.533) 0px 2px 12px; }
  .joystick small { position: absolute; bottom: -13px; font: 6px var(--mono); letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.604); }
  .touch-actions { position: absolute; right: 20px; bottom: 33px; display: flex; align-items: end; gap: 13px; }
  .action-btn { border: 1px solid rgba(255, 255, 255, 0.44); border-radius: 50%; display: grid; place-items: center; align-content: center; gap: 1px; background: rgba(21, 32, 23, 0.72); backdrop-filter: blur(6px); }
  .action-btn span { font-size: 24px; line-height: 24px; color: var(--gold); }
  .action-btn small { font: 6px var(--mono); letter-spacing: 0.05em; }
  .jump-btn { width: 55px; height: 55px; }
  .cast-btn { width: 71px; height: 71px; border-color: rgb(228, 200, 122); background: rgba(58, 49, 35, 0.75); }
  .cast-btn span { font-size: 26px; }
